  const viewModule:Partial<Record<View,Module>>={design:'design',boq:'boq',attendance:'wages',wagebills:'wages',people:'wages',materials:'materials',variations:'variations','client-portal':'portal',reports:'portal'};
  function visible(v:View){const mod=viewModule[v];if(mod&&!(selected?enabled(state,selected,mod):state.suite.modules[mod]))return false;if(role==='client')return v==='overview';if(role==='architect')return ['overview','site','design','pilot'].includes(v);if(role==='foreman')return !['boq','variations','client-portal','settings','team'].includes(v);return true;}
  const financials=project?projectFinancials(state,selected):null;
